$psi = New-Object System.Diagnostics.ProcessStartInfo
$psi.FileName = "$env:LOCALAPPDATA\Programs\Horizun\MCP\server\horizun-mcp.exe"
$psi.UseShellExecute = $false
$psi.RedirectStandardInput = $true
$psi.RedirectStandardOutput = $true
$psi.RedirectStandardError = $true
$psi.StandardOutputEncoding = [System.Text.Encoding]::UTF8
$p = [System.Diagnostics.Process]::Start($psi)
$errTask = $p.StandardError.ReadToEndAsync()
$utf8 = New-Object System.Text.UTF8Encoding($false)
$in = New-Object System.IO.StreamWriter($p.StandardInput.BaseStream, $utf8)
$in.AutoFlush = $true

function Send($obj) { $in.WriteLine(($obj | ConvertTo-Json -Depth 10 -Compress)) }
function Recv($id, $timeoutSec) {
    $deadline = (Get-Date).AddSeconds($timeoutSec)
    while ((Get-Date) -lt $deadline) {
        $t = $p.StandardOutput.ReadLineAsync()
        if (-not $t.Wait([int](($deadline - (Get-Date)).TotalMilliseconds))) { return "TIMEOUT" }
        $line = $t.Result
        if ($null -eq $line) { return "EOF" }
        try { $m = $line | ConvertFrom-Json } catch { continue }
        if ($m.id -eq $id) { return $line }
    }
    return "TIMEOUT"
}

Send @{ jsonrpc = "2.0"; id = 1; method = "initialize"; params = @{ protocolVersion = "2025-06-18"; capabilities = @{}; clientInfo = @{ name = "probe"; version = "1" } } }
$r = Recv 1 30
"=== initialize ==="; if ($r.Length -gt 600) { $r.Substring(0,600) } else { $r }
Send @{ jsonrpc = "2.0"; method = "notifications/initialized" }
Send @{ jsonrpc = "2.0"; id = 2; method = "tools/list"; params = @{} }
$r = Recv 2 30
"=== tools/list ==="
try { $tl = ($r | ConvertFrom-Json).result.tools; "tool count: $($tl.Count)"; "has horizun_health: $([bool]($tl | Where-Object name -eq 'horizun_health'))" } catch { $r }
Send @{ jsonrpc = "2.0"; id = 3; method = "tools/call"; params = @{ name = "horizun_health"; arguments = @{} } }
$r = Recv 3 60
"=== horizun_health ==="; $r
try { $p.StandardInput.Close() } catch {}
if (-not $p.WaitForExit(5000)) { $p.Kill() }
$e = $errTask.Result
if ($e) { "=== stderr (tail) ==="; ($e -split "`n" | Select-Object -Last 15) -join "`n" }

